<?php
chdir(__DIR__.'/../public'); require '../app/bootstrap.php';$db=new Database();$key=date('Y-m');
try{$db->query("INSERT INTO scheduled_job_runs(job_key,operation_key,status) VALUES('candidate_retention',?,'running')");$db->execute([$key]);}catch(Throwable $e){echo "La retención de este mes ya fue procesada.\n";exit(0);}
try{$db->query("SELECT c.id,ja.id application_id,ja.cv_path FROM candidates c LEFT JOIN job_applications ja ON ja.candidate_id=c.id WHERE c.retention_until<CURDATE() AND c.anonymized_at IS NULL AND NOT EXISTS(SELECT 1 FROM job_applications x WHERE x.candidate_id=c.id AND x.status='hired')");$rows=$db->resultSet();foreach($rows as $r){if($r->cv_path){$p=dirname(APPROOT).'/storage/private/'.$r->cv_path;if(is_file($p))@unlink($p);}$db->query("UPDATE job_applications SET cv_path='',cv_original_name='eliminado',ai_result_json=NULL WHERE id=?");$db->execute([(int)$r->application_id]);$db->query("UPDATE candidates SET email=CONCAT('anon+',id,'@invalid.local'),full_name='Candidato anonimizado',phone=NULL,token_hash=SHA2(CONCAT('anon',id,RAND()),256),anonymized_at=NOW() WHERE id=?");$db->execute([(int)$r->id]);}$db->query("UPDATE scheduled_job_runs SET status='success',finished_at=NOW(),details_json=? WHERE job_key='candidate_retention' AND operation_key=?");$db->execute([json_encode(['anonymized'=>count($rows)]),$key]);echo count($rows)." candidatos anonimizados.\n";}catch(Throwable $e){$db->query("UPDATE scheduled_job_runs SET status='failed',finished_at=NOW(),details_json=? WHERE job_key='candidate_retention' AND operation_key=?");$db->execute([json_encode(['error'=>$e->getMessage()]),$key]);throw $e;}
